// Whole-table analysis on top of engine.evaluate(): every design at once.
// Used by the design explorer, "what matters most", the missions, and sim/findings (Node).
import { evaluate } from './engine.js';

/** kWh/yr generated by 1 % of usable roof. */
export function kwhPerPct(city) {
  const m = city.meta, eco = m.economics, kwpMax = m.geometry.roof_area * eco.solar.usable_roof_fraction * eco.solar.kwp_per_m2;
  return kwpMax / 100 * m.constants.solar_kwh_per_kwp_monthly.reduce((a, b) => a + b, 0);
}

/** Solar coverage needed for net zero, rounded up to 5 %; null if more than the whole usable roof. */
export function sizePv(city, use) {
  const p = Math.ceil(use / kwhPerPct(city) / 5 - 1e-9) * 5;
  return p <= 100 ? Math.max(0, p) : null;
}

/**
 * Evaluate every design in the table.
 * opts.ac: AC efficiency key, or 'best' to try all and keep the cheapest that meets the goal.
 * opts.pv: a fixed coverage (0–100), or 'nz' to size solar for net zero (full roof if net zero is impossible).
 * Returns compact typed arrays indexed by row.
 */
export function evaluateAll(city, settings, opts = {}) {
  const n = city.meta.rows, acKeys = Object.keys(city.meta.economics.ac_efficiency);
  const out = { n, eui: new Float32Array(n), comfort: new Float32Array(n), cost: new Float32Array(n),
                nz: new Float32Array(n), bill: new Float32Array(n), pv: new Uint8Array(n), ac: new Uint8Array(n),
                acKeys };
  for (let row = 0; row < n; row++) {
    const d0 = city.designOf(row);
    const acs = opts.ac === 'best' ? acKeys : [opts.ac || '3star'];
    let best = null, bestAc = 0;
    for (let a = 0; a < acs.length; a++) {
      let d = { ...d0, ac: acs[a], pv: opts.pv === 'nz' ? 0 : (opts.pv ?? 0) };
      let r = evaluate(city, d, settings);
      if (!r) continue;
      if (opts.pv === 'nz') {
        const p = sizePv(city, r.use);
        d = { ...d, pv: p ?? 100 }; r = evaluate(city, d, settings);
      }
      if (!best || r.cost < best.cost) { best = r; bestAc = acKeys.indexOf(acs[a]); }
      if (!city.meta.cooling_modes[d0.cooling].ac) break;  // AC efficiency does not matter without AC
    }
    if (!best) { out.eui[row] = NaN; continue; }
    out.eui[row] = best.eui; out.comfort[row] = best.comfort; out.cost[row] = best.cost;
    out.nz[row] = best.nz; out.bill[row] = best.annualBill; out.pv[row] = best.design.pv; out.ac[row] = bestAc;
  }
  return out;
}

/** Rows on the cost / energy-use Pareto front among rows that pass keep(row). */
export function paretoFront(all, keep = () => true) {
  const rows = [];
  for (let i = 0; i < all.n; i++) if (!Number.isNaN(all.eui[i]) && keep(i)) rows.push(i);
  rows.sort((a, b) => all.cost[a] - all.cost[b] || all.eui[a] - all.eui[b]);
  const front = []; let bestEui = Infinity;
  for (const i of rows) if (all.eui[i] < bestEui - 1e-6) { front.push(i); bestEui = all.eui[i]; }
  return front;
}

/**
 * What matters most: for each option, the average result of each choice over every other combination
 * (a "main effect"). swing = biggest difference between choices.
 */
export function importance(city, all) {
  const res = [];
  const opts = city.options;
  for (let k = 0; k < opts.length; k++) {
    const o = opts[k], nc = o.choices.length;
    const sE = new Float64Array(nc), sC = new Float64Array(nc), sK = new Float64Array(nc), cnt = new Float64Array(nc);
    let stride = 1; for (let j = k + 1; j < opts.length; j++) stride *= opts[j].choices.length;
    for (let row = 0; row < all.n; row++) {
      if (Number.isNaN(all.eui[row])) continue;
      const c = Math.floor(row / stride) % nc;
      sE[c] += all.eui[row]; sC[c] += all.comfort[row]; sK[c] += all.cost[row]; cnt[c]++;
    }
    const choices = o.choices.map((ch, c) => ({ id: ch.id, label: ch.label, eui: sE[c] / cnt[c], comfort: sC[c] / cnt[c], cost: sK[c] / cnt[c] }));
    const span = key => Math.max(...choices.map(c => c[key])) - Math.min(...choices.map(c => c[key]));
    res.push({ id: o.id, label: o.label, choices, swingEui: span('eui'), swingComfort: span('comfort'), swingCost: span('cost') });
  }
  return res.sort((a, b) => b.swingEui - a.swingEui);
}

/** Best design for each mission, searched over every design, all AC efficiencies and solar sizes. */
export const MISSIONS = [
  { id: 'cheapest_nz', title: 'Cheapest net zero',
    goal: lv => `Reach net zero and ≥ ${lv.comfort_target}% comfort for the lowest cost.`,
    ok: (r, lv) => r.nz >= 1 - 1e-9 && r.comfort >= lv.comfort_target, better: (a, b) => a.cost < b.cost,
    metric: r => r.cost, unit: 'cost' },
  { id: 'no_ac', title: 'No-AC challenge',
    goal: lv => `No air-conditioning at all. Stay comfortable ≥ ${lv.noac_comfort_target}% of the time and reach net zero.`,
    ok: (r, lv) => !r.acOn && r.nz >= 1 - 1e-9 && r.comfort >= lv.noac_comfort_target, better: (a, b) => a.comfort > b.comfort || (a.comfort === b.comfort && a.cost < b.cost),
    metric: r => r.comfort, unit: 'comfort' },
  { id: 'lowest_eui', title: 'Lowest energy within budget',
    goal: lv => `Use as little energy as possible with ≥ ${lv.comfort_target}% comfort, without going over budget.`,
    ok: (r, lv) => r.cost <= lv.budget_rs && r.comfort >= lv.comfort_target, better: (a, b) => a.eui < b.eui,
    metric: r => r.eui, unit: 'eui' },
];

export function missionBest(city, settings, level, mission) {
  const acKeys = Object.keys(city.meta.economics.ac_efficiency);
  let best = null;
  for (let row = 0; row < city.meta.rows; row++) {
    if (!city.has(row)) continue;
    const d0 = city.designOf(row), acOn = city.meta.cooling_modes[d0.cooling].ac;
    for (const ac of acOn ? acKeys : ['3star']) {
      const r0 = evaluate(city, { ...d0, ac, pv: 0 }, settings);
      const p = sizePv(city, r0.use);
      const pvs = mission.id === 'lowest_eui' ? [0, p ?? 100] : p === null ? [100] : [p];
      for (const pv of pvs) {
        const r = pv === 0 ? r0 : evaluate(city, { ...d0, ac, pv }, settings);
        r.acOn = acOn;
        if (mission.ok(r, level) && (!best || mission.better(r, best))) best = r;
      }
    }
  }
  return best;
}
